def _prepare_fold(
    fe: CouponFeatureEngineer,
    df: pd.DataFrame,
    fold_id: Optional[int] = None,
    oof_folds=None,
):
    """NN inputs: integer codes (unchanged embedding cards) + numeric block.

    The numeric block is the raw numeric features followed by the smoothed
    target-encoding block (fold-specific maps when ``fold_id`` is given).
    """
    Xfe = fe.transform(df).reindex(columns=fe.feature_names, fill_value=0.0)
    cat_cols, num_cols = split_feature_columns(fe.feature_names)
    cat = (
        np.nan_to_num(Xfe[cat_cols].values, nan=-1.0)
        if cat_cols
        else np.zeros((len(Xfe), 0))
    )
    num = (
        Xfe[num_cols].values.astype(np.float32)
        if num_cols
        else np.zeros((len(Xfe), 0), dtype=np.float32)
    )
    if oof_folds is not None:
        te = fe.transform_target_encoding_oof(df, oof_folds)
    else:
        te = fe.transform_target_encoding(df, fold_id=fold_id)
    if te.shape[1] > 0:
        num = np.concatenate([num, te.astype(np.float32)], axis=1)
        num_cols = list(num_cols) + ["te_" + c for c in fe.te_col_names]
    return cat, num, cat_cols, num_cols


def _cat_sources(fe: CouponFeatureEngineer) -> List[str]:
    """Raw column names backing the ``cat_*`` columns, in block order."""
    return [c[len("cat_"):] for c in list(getattr(fe, "cat_cols", []) or [])]


def _prepare_gbdt_matrix(
    fe: CouponFeatureEngineer,
    df: pd.DataFrame,
    feature_names: Optional[Sequence[str]] = None,
    fold_id: Optional[int] = None,
    oof_folds=None,
) -> np.ndarray:
    """GBDT matrix: NATIVE categorical block + numeric block + smoothed TE.

    The categorical block keeps integer-coded ``cat_*`` identity and
    interaction levels (missing -> ``NaN``) so HistGradientBoostingClassifier
    can use its native categorical splits instead of the false ordinal
    ordering the trees used to see. The per-column mask is stored on the
    fitted engineer (``gbdt_cat_flags``) so prediction rebuilds it identically.

    ``feature_names`` is accepted for backwards compatibility; the column
    layout is derived from the fitted engineer so train and predict agree.
    """
    Xfe = fe.transform(df).reindex(columns=fe.feature_names, fill_value=0.0)
    cat_cols, num_cols = split_feature_columns(fe.feature_names)
    blocks: List[np.ndarray] = []
    flags: List[bool] = []
    if cat_cols:
        codes = np.nan_to_num(Xfe[cat_cols].values, nan=-1.0).astype(np.float64)
        codes = np.where(codes < 0.0, np.nan, codes).astype(np.float32)
        blocks.append(codes)
        flags.extend([True] * len(cat_cols))
    if num_cols:
        vals = Xfe[num_cols].values.astype(np.float32)
        vals = np.nan_to_num(vals, nan=0.0, posinf=0.0, neginf=0.0)
        blocks.append(vals)
        flags.extend([False] * len(num_cols))
    if oof_folds is not None:
        te = fe.transform_target_encoding_oof(df, oof_folds)
    else:
        te = fe.transform_target_encoding(df, fold_id=fold_id)
    if te.shape[1] > 0:
        te = np.nan_to_num(
            te.astype(np.float32), nan=0.5, posinf=0.5, neginf=0.5
        )
        blocks.append(te)
        flags.extend([False] * te.shape[1])
    if blocks:
        X = np.concatenate(blocks, axis=1).astype(np.float32)
    else:
        X = np.zeros((len(Xfe), 0), dtype=np.float32)
    fe.gbdt_cat_flags = flags
    return X


def _prepare_et_matrix(
    fe: CouponFeatureEngineer,
    df: pd.DataFrame,
    fold_id: Optional[int] = None,
    oof_folds=None,
) -> np.ndarray:
    """ExtraTrees matrix: numeric + TE + one-hot low-cardinality categoricals.

    ``fold_id`` selects the fold-specific TE maps so OOF rows are encoded with
    statistics that never saw their own label.
    """
    Xfe = fe.transform(df).reindex(columns=fe.feature_names, fill_value=0.0)
    _cat_cols, num_cols = split_feature_columns(fe.feature_names)
    blocks: List[np.ndarray] = []
    if num_cols:
        blocks.append(
            np.nan_to_num(
                Xfe[num_cols].values.astype(np.float32),
                nan=0.0,
                posinf=0.0,
                neginf=0.0,
            )
        )
    cards_by_name = dict(getattr(fe, "et_onehot_cards", {}) or {})
    oh_parts: List[np.ndarray] = []
    for c in list(getattr(fe, "et_onehot_cols", []) or []):
        cards = int(cards_by_name.get(c, 0))
        col = "cat_" + c
        if cards <= 0 or col not in Xfe.columns:
            continue
        codes = np.nan_to_num(Xfe[col].values, nan=-1.0).astype(np.int64)
        oh = np.zeros((len(Xfe), cards), dtype=np.float32)
        ok = (codes >= 0) & (codes < cards)
        rows = np.where(ok)[0]
        oh[rows, codes[ok]] = 1.0
        oh_parts.append(oh)
    if oh_parts:
        blocks.append(np.concatenate(oh_parts, axis=1))
    if oof_folds is not None:
        te = fe.transform_target_encoding_oof(df, oof_folds)
    else:
        te = fe.transform_target_encoding(df, fold_id=fold_id)
    if te.shape[1] > 0:
        blocks.append(
            np.nan_to_num(te.astype(np.float32), nan=0.5, posinf=0.5, neginf=0.5)
        )
    if not blocks:
        return np.zeros((len(Xfe), 0), dtype=np.float32)
    return np.concatenate(blocks, axis=1).astype(np.float32)


def _fit_extra_trees(X_tr: np.ndarray, y_tr: np.ndarray, seed: int = 7):
    """Bagged, decorrelated tree member trained on one fold (or all rows)."""
    if not HAS_ET or ExtraTreesClassifier is None or X_tr.shape[1] == 0:
        return None
    try:
        clf = ExtraTreesClassifier(
            n_estimators=400,
            max_features="sqrt",
            min_samples_leaf=2,
            n_jobs=2,
            random_state=int(seed),
        )
        clf.fit(X_tr, y_tr)
    except Exception as exc:  # pragma: no cover - defensive
        print(f"[train] ExtraTrees skipped: {exc}")
        return None
    return clf


def _predict_et(models: List[Any], X: np.ndarray) -> Optional[np.ndarray]:
    if not models:
        return None
    probas = [np.asarray(m.predict_proba(X), dtype=np.float64) for m in models]
    return np.mean(probas, axis=0)


def _train_gbdt(
    X_tr: np.ndarray, y_tr: np.ndarray, cat_mask: Optional[np.ndarray] = None
) -> List[Any]:
    """Train a small diverse ensemble of gradient-boosted tree models.

    ``cat_mask`` (bool per column) enables HistGradientBoostingClassifier's
    native categorical splits for the interaction / identity block.
    """
    if not HAS_GBDT:
        return []
    mask = None
    if cat_mask is not None:
        cand = np.asarray(cat_mask, dtype=bool).ravel()
        if cand.size == X_tr.shape[1] and cand.any():
            mask = cand
    models: List[Any] = []
    for gc in GBDT_CONFIGS:
        clf = None
        if mask is not None:
            try:
                kwargs = dict(gc)
                kwargs["categorical_features"] = mask
                clf = HistGradientBoostingClassifier(**kwargs)
            except (TypeError, ValueError):
                clf = None
        if clf is None:
            try:
                clf = HistGradientBoostingClassifier(**gc)
            except Exception:
                clf = GradientBoostingClassifier(
                    n_estimators=300,
                    max_depth=5,
                    learning_rate=0.05,
                    random_state=int(gc.get("random_state", 42)),
                )
        clf.fit(X_tr, y_tr)
        models.append(clf)
    return models


def _predict_gbdt(models: List[Any], X: np.ndarray) -> Optional[np.ndarray]:
    if not models:
        return None
    probas = [np.asarray(m.predict_proba(X), dtype=np.float64) for m in models]
    return np.mean(probas, axis=0)


def _predict_proba_single(
    model: nn.Module,
    cat_shifted: np.ndarray,
    num_mat: np.ndarray,
    batch_size: int = 512,
) -> np.ndarray:
    device = get_device()
    model.to(device).eval()
    chunks: List[np.ndarray] = []
    n = len(cat_shifted)
    for start in range(0, n, batch_size):
        end = min(start + batch_size, n)
        xc = torch.from_numpy(cat_shifted[start:end]).long().to(device)
        xn = torch.from_numpy(num_mat[start:end].astype(np.float32)).to(device)
        with torch.no_grad():
            chunks.append(torch.softmax(model(xc, xn), dim=1).cpu().numpy())
    if not chunks:
        return np.zeros((n, 2), dtype=np.float64)
    return np.concatenate(chunks, axis=0).astype(np.float64)


def _search_blend(
    p_nn: np.ndarray, p_gbdt: np.ndarray, y_idx: np.ndarray
) -> Tuple[float, float]:
    """Pick alpha (NN weight) maximizing accuracy of blended argmax on OOF."""
    best_alpha = 1.0
    best_acc = float((p_nn.argmax(1) == y_idx).mean())
    for alpha in np.linspace(0.0, 1.0, 21):
        pred = (float(alpha) * p_nn + (1.0 - float(alpha)) * p_gbdt).argmax(1)
        acc = float((pred == y_idx).mean())
        if acc > best_acc:
            best_acc, best_alpha = acc, float(alpha)
    return best_alpha, best_acc


def _simplex_grid(k: int, step: float = 0.05):
    """Yield weight tuples on the (k-1)-simplex, coarse grid of size ``step``."""
    vals = np.arange(0.0, 1.0 + 1e-9, step)
    if k <= 1:
        yield (1.0,)
        return
    stack: List[Tuple[float, ...]] = [tuple()]
    for _ in range(k - 1):
        nxt: List[Tuple[float, ...]] = []
        for pre in stack:
            s = float(sum(pre))
            for v in vals.tolist():
                if s + v <= 1.0 + 1e-9:
                    nxt.append(pre + (float(v),))
        stack = nxt
    for pre in stack:
        yield pre + (float(1.0 - sum(pre)),)


def _search_blend_weights(
    probs: List[Optional[np.ndarray]],
    y_idx: np.ndarray,
    step: float = 0.05,
) -> Tuple[List[float], float]:
    """Non-negative weights (normalised to 1) maximising OOF accuracy."""
    comps = [
        np.asarray(p, dtype=np.float64)
        for p in probs
        if p is not None and np.asarray(p).size > 0
    ]
    if not comps:
        return [], 0.0
    y_idx = np.asarray(y_idx).ravel()
    k = len(comps)
    if k == 1:
        return [1.0], float((comps[0].argmax(1) == y_idx).mean())
    best_w = np.full(k, 1.0 / k, dtype=np.float64)
    blended = sum(best_w[i] * comps[i] for i in range(k))
    best_acc = float((blended.argmax(1) == y_idx).mean())
    for combo in _simplex_grid(k, step):
        w = np.asarray(combo, dtype=np.float64)
        tot = float(w.sum())
        if tot <= 1e-9:
            continue
        w = w / tot
        blended = sum(w[i] * comps[i] for i in range(k))
        acc = float((blended.argmax(1) == y_idx).mean())
        if acc > best_acc + 1e-12:
            best_acc, best_w = acc, w
    tot = float(best_w.sum())
    best_w = best_w / tot if tot > 0 else np.full(k, 1.0 / k)
    return [float(x) for x in best_w.tolist()], best_acc


def _save_bundle(
    model_dir,
    fe,
    normalizer,
    cat_cols,
    num_cols,
    cards,
    label_map,
    cfg,
    models,
    epochs,
    gbdt_models=None,
    blend_alpha=1.0,
    extra_trees_models=None,
    blend_weights=None,
) -> str:
    os.makedirs(model_dir, exist_ok=True)
    path = os.path.join(model_dir, BUNDLE_NAME)
    bundle = {
        "fe": fe,
        "feature_names": list(fe.feature_names),
        "normalizer_state": normalizer.state_dict(),
        "cat_cols": list(cat_cols),
        "num_cols": list(num_cols),
        "cards": list(cards),
        "label_map": list(label_map),
        "cfg": dict(cfg.__dict__),
        "state_dicts": [m.state_dict() for m in models],
        "epochs": int(epochs),
        "gbdt_models": list(gbdt_models) if gbdt_models else [],
        "extra_trees_models": (
            list(extra_trees_models) if extra_trees_models else []
        ),
        "blend_alpha": float(blend_alpha),
        "blend_weights": [float(w) for w in (blend_weights or [])],
        "gbdt_cat_flags": list(getattr(fe, "gbdt_cat_flags", []) or []),
        "et_onehot_cols": list(getattr(fe, "et_onehot_cols", []) or []),
        "et_onehot_cards": dict(getattr(fe, "et_onehot_cards", {}) or {}),
        "nn_cfg": {
            "emb_dim": int(getattr(cfg, "emb_dim", 8)),
            "hidden": int(getattr(cfg, "hidden", 128)),
            "dropout": float(getattr(cfg, "dropout", 0.2)),
        },
        # Smoothed target-encoding state (also carried inside "fe"); persisted
        # explicitly so prediction can verify it never refits.
        "te_maps": fe.te_maps,
        "te_prior": float(fe.te_prior),
        "te_m": int(fe.te_m),
        "te_col_names": list(fe.te_col_names),
    }
    torch.save(bundle, path)
    return path


def _load_bundle(model_dir):
    path = os.path.join(model_dir, BUNDLE_NAME)
    try:
        bundle = torch.load(path, map_location="cpu", weights_only=False)
    except TypeError:
        bundle = torch.load(path, map_location="cpu")
    return bundle


def run_predict(data_dir, model_dir, output_path) -> None:
    bundle = _load_bundle(model_dir)
    fe = bundle["fe"]
    normalizer = Normalizer()
    normalizer.load_state_dict(bundle["normalizer_state"])
    cards = [int(c) for c in bundle["cards"]]
    label_map = bundle["label_map"]
    n_classes = len(label_map)
    num_cols = bundle["num_cols"]
    nn_cfg = bundle.get("nn_cfg") or {}

    models: List[nn.Module] = []
    for sd in bundle.get("state_dicts", []):
        m = CouponModel(
            cards,
            len(num_cols),
            n_classes,
            int(nn_cfg.get("emb_dim", 8)),
            int(nn_cfg.get("hidden", 128)),
            float(nn_cfg.get("dropout", 0.2)),
        )
        m.load_state_dict(sd)
        m.eval()
        models.append(m)

    features, _schema = load_predict_data(data_dir)
    # Apply the SAVED maps only (full-training fit); never refit here. Unseen /
    # missing categories fall back to the stored global prior.
    if not getattr(fe, "te_col_names", None) and bundle.get("te_col_names"):
        fe.te_col_names = list(bundle["te_col_names"])
        fe.te_maps = bundle.get("te_maps", {}) or {}
        fe.te_prior = float(bundle.get("te_prior", 0.5))
        fe.te_m = int(bundle.get("te_m", 20))
    cat, num, _cat_cols, _num_cols = _prepare_fold(fe, features)
    num_n = normalizer.transform(num)
    cat_shifted, cards = _shift_cat(cat, cards)

    proba = _ensemble_proba(models, cat_shifted, num_n, batch_size=512)
    if proba is None:
        proba = np.zeros((len(features), n_classes), dtype=np.float64)
        proba[:, 0] = 1.0

    gbdt_models = bundle.get("gbdt_models", []) or []
    et_models = bundle.get("extra_trees_models", []) or []
    blend_alpha = float(bundle.get("blend_alpha", 1.0))
    comps: List[np.ndarray] = [np.asarray(proba, dtype=np.float64)]
    if gbdt_models:
        X_gbdt = _prepare_gbdt_matrix(fe, features, bundle["feature_names"])
        proba_gbdt = _predict_gbdt(gbdt_models, X_gbdt)
        if proba_gbdt is not None and proba_gbdt.shape == proba.shape:
            comps.append(np.asarray(proba_gbdt, dtype=np.float64))
    X_et = None
    if et_models:
        X_et = _prepare_et_matrix(fe, features)
        proba_et = _predict_et(et_models, X_et)
        if proba_et is not None and proba_et.shape == proba.shape:
            comps.append(np.asarray(proba_et, dtype=np.float64))

    blend_weights = [float(w) for w in (bundle.get("blend_weights") or [])]
    if blend_weights and len(blend_weights) == len(comps):
        w = np.asarray(blend_weights, dtype=np.float64)
        tot = float(w.sum())
        if tot > 0:
            w = w / tot
        proba = sum(w[i] * comps[i] for i in range(len(comps)))
        print(
            f"[predict] blend weights={np.round(w, 3).tolist()} "
            f"(NN={len(models)}, GBDT={len(gbdt_models)}, ET={len(et_models)})"
        )
    elif len(comps) == 2:
        proba = blend_alpha * comps[0] + (1.0 - blend_alpha) * comps[1]
        print(
            f"[predict] blended alpha_nn={blend_alpha:.2f} "
            f"(NN={len(models)}, GBDT={len(gbdt_models)})"
        )

    idx_pred = np.argmax(proba, axis=1)
    preds = [label_map[int(i)] for i in idx_pred]

    out = pd.DataFrame(
        {
            "row_id": np.arange(len(features), dtype=np.int64),
            "prediction": preds,
        }
    )
    out_dir = os.path.dirname(output_path)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    out.to_csv(output_path, index=False)
    print(f"[predict] wrote {len(out)} rows -> {output_path}")


def main() -> None:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)

    p_train = sub.add_parser("train")
    p_train.add_argument("--data", required=True)
    p_train.add_argument("--model", required=True)

    p_pred = sub.add_parser("predict")
    p_pred.add_argument("--data", required=True)
    p_pred.add_argument("--model", required=True)
    p_pred.add_argument("--output", required=True)

    args = ap.parse_args()
    if args.cmd == "train":
        run_train(args.data, args.model)
    else:
        run_predict(args.data, args.model, args.output)


if __name__ == "__main__":
    main()

# solution.py
"""
Coupon acceptance prediction — improved merged pipeline.

Stages:
  1) Leakage-safe feature engineering (fit on TRAIN rows only).
  2) Base learners: LGBM (with fold-fold target-encoded interactions),
     CatBoost (raw categoricals), DeepFM (diversity via MLP).
  3) 5-fold stratified train-only CV -> OOF probs -> metric-aligned selection
     among {lgb_avg, cb_avg, soft_vote, meta_lgb} + threshold tuning;
     final refit; full bundle persisted; fresh-process predict.

CLI:
  python solution.py train   --data /data --model /model
  python solution.py predict --data /data --model /model --output /output/predictions.csv
"""

from __future__ import annotations

import os
import re
import json
import math
import argparse
from typing import List, Optional, Sequence, Tuple

import joblib
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import accuracy_score

# ===========================================================================
# Step 1: Data loading, cleaning and reusable feature engineering
# ===========================================================================
VENUE_COLS = [
    "Bar",
    "CoffeeHouse",
    "CarryAway",
    "RestaurantLessThan20",
    "Restaurant20To50",
]
VENUE_INDEX = {c: i for i, c in enumerate(VENUE_COLS)}

FREQ_MAP = {"never": 0, "less1": 1, "1~3": 2, "4~8": 3, "gt8": 4}

TIME_MAP = {"7am": 0, "10am": 1, "2pm": 2, "6pm": 3, "10pm": 4}
TIME_HOUR = {"7am": 7, "10am": 10, "2pm": 14, "6pm": 18, "10pm": 22}

RAW_CAT_COLS = [
    "time",
    "expiration",
    "gender",
    "maritalStatus",
    "education",
    "occupation",
    "income",
    "age",
]

# Interaction categoricals that get CV-safe target encoding.
INTERACTION_COLS = [
    "coupon_x_exp",
    "coupon_x_dir",
    "coupon_x_age",
    "coupon_x_time",
    "gender_x_coupon",
    "children_x_coupon",
    "distance_x_coupon",
    "time_x_exp",
]


def _norm(s):
    return str(s).strip().lower()


def _coupon_to_venue(coupon_val):
    s = _norm(coupon_val)
    if "bar" in s:
        return "Bar"
    if "coffee" in s or "cafe" in s:
        return "CoffeeHouse"
    if "carry" in s or "take" in s or "away" in s:
        return "CarryAway"
    if "rest" in s:
        if "<" in s or "less" in s or "under" in s:
            return "RestaurantLessThan20"
        if "20" in s and "50" in s:
            return "Restaurant20To50"
        if "20" in s:
            return "Restaurant20To50"
        return "RestaurantLessThan20"
    return None


def _age_ord(v):
    s = _norm(v)
    if "below" in s or "under" in s:
        return 0
    if "plus" in s or "+" in s:
        return 7
    m = re.search(r"\d+", s)
    if m:
        n = int(m.group())
        return int(max(1, min(6, (n - 21) // 5 + 1)))
    return -1


def _income_ord(v):
    s = _norm(v).replace(",", "").replace(" ", "")
    if "less" in s:
        return 0
    if "more" in s or "100000" in s:
        return 8
    m = re.search(r"(\d+)", s)
    if m:
        lo = int(m.group(1))
        return int(max(0, min(8, lo // 12500)))
    return -1


def _edu_ord(v):
    s = _norm(v)
    if "some high" in s:
        return 0
    if "high school" in s and "some" not in s:
        return 1
    if "some college" in s or "no degree" in s:
        return 2
    if "associate" in s:
        return 3
    if "bachelor" in s:
        return 4
    if "graduate" in s or "master" in s or "doctor" in s:
        return 5
    return -1


def _time_ord(v):
    return TIME_MAP.get(_norm(v).replace(" ", ""), -1)


def _time_hour(v):
    return TIME_HOUR.get(_norm(v).replace(" ", ""), -1)


class CouponFeatureEngineer:
    """Deterministic engineering + target-free freq encodings (fit on train)."""

    def __init__(self):
        self.freq_maps_ = {}
        self.freq_encode_cols_ = []
        self.freq_col_names_ = []
        self.categorical_columns = []
        self.numeric_columns = []
        self._cat_base = []
        self._num_base = []
        self.fitted = False

    def _build_base(self, X):
        X = X.copy()
        n = len(X)
        out = pd.DataFrame(index=X.index)

        coupon = X["coupon"].astype(str)
        out["coupon"] = coupon.str.strip()
        out["coupon_canon"] = coupon.map(lambda c: _coupon_to_venue(c) or "unknown")

        for col in RAW_CAT_COLS:
            out[col] = X[col].astype(str).str.strip()

        out["direction"] = np.where(
            pd.to_numeric(X["direction_same"], errors="coerce").fillna(0) == 1,
            "same",
            "opp",
        )

        for col in VENUE_COLS:
            out[col] = (
                X[col]
                .astype(str)
                .str.strip()
                .str.lower()
                .replace({"nan": "never", "": "never", "none": "never"})
            )

        out["has_children"] = (
            pd.to_numeric(X["has_children"], errors="coerce").fillna(0).astype(int)
        )
        out["temperature"] = pd.to_numeric(X["temperature"], errors="coerce")

        g5 = pd.to_numeric(X["toCoupon_GEQ5min"], errors="coerce").fillna(0)
        g15 = pd.to_numeric(X["toCoupon_GEQ15min"], errors="coerce").fillna(0)
        g25 = pd.to_numeric(X["toCoupon_GEQ25min"], errors="coerce").fillna(0)
        out["distance_level"] = (
            (g5 > 0).astype(int) + (g15 > 0).astype(int) + (g25 > 0).astype(int)
        )
        out["is_25min"] = (g25 > 0).astype(int)
        out["is_15min"] = (g15 > 0).astype(int)
        out["is_5min_only"] = ((g15 == 0) & (g25 == 0)).astype(int)
        out["direction_same"] = (
            pd.to_numeric(X["direction_same"], errors="coerce").fillna(0).astype(int)
        )
        out["is_2h"] = (
            out["expiration"]
            .str.lower()
            .str.replace(" ", "", regex=False)
            .str.contains("2h")
            .astype(int)
        )

        out["age_ord"] = out["age"].map(_age_ord)
        out["income_ord"] = out["income"].map(_income_ord)
        out["education_ord"] = out["education"].map(_edu_ord)
        out["time_ord"] = out["time"].map(_time_ord)
        out["hour"] = out["time"].map(_time_hour)

        freq_arr = {c: out[c].map(FREQ_MAP).fillna(0).astype(int) for c in VENUE_COLS}
        A = np.column_stack([freq_arr[c].values for c in VENUE_COLS])
        venue_names = out["coupon_canon"].values
        vidx = np.array([VENUE_INDEX.get(v, -1) for v in venue_names])
        matched = np.where(
            vidx >= 0, A[np.arange(n), np.clip(vidx, 0, len(VENUE_COLS) - 1)], 0
        )

        out["coupon_venue_freq"] = matched.astype(int)
        out["coupon_venue_visited"] = (matched > 0).astype(int)
        out["total_engagement"] = A.sum(1)
        out["mean_engagement"] = A.mean(1)
        out["engagement_std"] = A.std(1)
        out["matched_minus_mean"] = matched - A.mean(1)
        out["n_venues_visited"] = (A > 0).sum(1)

        occ = out["occupation"].str.lower()
        out["is_student"] = occ.str.contains("student").astype(int)
        out["is_retired"] = occ.str.contains("retired").astype(int)
        out["is_unemployed"] = occ.str.contains("unemploy").astype(int)
        out["gender_male"] = out["gender"].str.lower().str.startswith("m").astype(int)

        out["coupon_x_exp"] = out["coupon_canon"] + "_" + out["expiration"]
        out["coupon_x_dir"] = out["coupon_canon"] + "_" + out["direction"]
        out["gender_x_coupon"] = out["gender"] + "_" + out["coupon_canon"]
        out["children_x_coupon"] = (
            out["has_children"].astype(str) + "_" + out["coupon_canon"]
        )
        out["coupon_x_time"] = out["coupon_canon"] + "_" + out["time"]
        out["coupon_x_age"] = out["coupon_canon"] + "_" + out["age"]
        out["time_x_exp"] = out["time"] + "_" + out["expiration"]
        out["distance_x_coupon"] = (
            out["distance_level"].astype(str) + "_" + out["coupon_canon"]
        )

        return out

    def fit(self, X):
        base = self._build_base(X)
        n = max(len(base), 1)

        self._cat_base = [
            c for c in base.columns if not pd.api.types.is_numeric_dtype(base[c])
        ]
        self._num_base = [c for c in base.columns if c not in self._cat_base]
        truly_num, truly_cat = [], list(self._cat_base)
        for c in self._num_base:
            coerced = pd.to_numeric(base[c], errors="coerce")
            if coerced.notna().sum() >= max(1, int(0.5 * len(base))):
                truly_num.append(c)
            else:
                truly_cat.append(c)
        self._cat_base = truly_cat
        self._num_base = truly_num

        self.freq_encode_cols_ = list(self._cat_base)
        self.freq_maps_ = {}
        for c in self.freq_encode_cols_:
            vc = base[c].value_counts()
            self.freq_maps_[c] = (vc / n).to_dict()

        self.freq_col_names_ = [f"freq_{c}" for c in self.freq_encode_cols_]
        self.categorical_columns = self._cat_base
        self.numeric_columns = self._num_base + self.freq_col_names_
        self.fitted = True
        return self

    def transform(self, X):
        if not self.fitted:
            raise RuntimeError("CouponFeatureEngineer must be fit before transform().")
        base = self._build_base(X)
        out = base.copy()
        for c in self.freq_encode_cols_:
            m = self.freq_maps_.get(c, {})
            out[f"freq_{c}"] = base[c].map(m).fillna(0.0).astype(float)
        return out

    def fit_transform(self, X):
        return self.fit(X).transform(X)

    def save(self, path):
        os.makedirs(path, exist_ok=True)
        joblib.dump(self, os.path.join(path, "feature_engineer.joblib"))

    @classmethod
    def load(cls, path):
        obj = joblib.load(os.path.join(path, "feature_engineer.joblib"))
        if not isinstance(obj, cls):
            raise TypeError("Loaded object is not a CouponFeatureEngineer.")
        return obj


def load_train_data(data_dir):
    with open(os.path.join(data_dir, "schema.json"), "r") as f:
        schema = json.load(f)
    features = pd.read_csv(os.path.join(data_dir, "features.csv"))
    labels_df = pd.read_csv(os.path.join(data_dir, "labels.csv"))
    if "label" in labels_df.columns:
        labels = labels_df["label"].values
    else:
        labels = labels_df.iloc[:, 0].values
    return features, labels, schema


def load_predict_data(data_dir):
    with open(os.path.join(data_dir, "schema.json"), "r") as f:
        schema = json.load(f)
    features = pd.read_csv(os.path.join(data_dir, "features.csv"))
    return features, schema


def make_stratified_folds(y, n_splits=5, seed=42):
    from sklearn.model_selection import StratifiedKFold

    y = np.asarray(y)
    skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=seed)
    return [(tr, va) for tr, va in skf.split(np.zeros(len(y)), y)]


# ===========================================================================
# Target encoding (leakage-safe; fit inside fold / full-train refit)
# ===========================================================================
def _fit_target_encoders(df, y, cols, prior_weight: float = 20.0):
    prior = float(np.mean(y))
    encoders = {}
    for c in cols:
        grp = pd.DataFrame({"v": df[c].astype(str).values, "y": np.asarray(y)})
        agg = grp.groupby("v")["y"].agg(["mean", "count"])
        smoothed = (agg["mean"] * agg["count"] + prior * prior_weight) / (
            agg["count"] + prior_weight
        )
        encoders[c] = (smoothed.to_dict(), prior)
    return encoders


def _apply_target_encoders(df, cols, encoders):
    n = len(df)
    out = np.zeros((n, len(cols)), dtype=np.float32)
    for j, c in enumerate(cols):
        m, prior = encoders[c]
        out[:, j] = df[c].astype(str).map(m).fillna(prior).values.astype(np.float32)
    return out


# ===========================================================================
# Step 2: Model design
# ===========================================================================
class FocalLoss(nn.Module):
    def __init__(self, alpha: float = 0.5, gamma: float = 2.0):
        super().__init__()
        self.alpha = float(alpha)
        self.gamma = float(gamma)

    def forward(self, logits: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        t = targets.float()
        ce = F.binary_cross_entropy_with_logits(logits, t, reduction="none")
        p = torch.sigmoid(logits)
        pt = torch.where(t == 1.0, p, 1.0 - p)
        focal = ((1.0 - pt) ** self.gamma) * ce
        alpha_t = torch.where(t == 1.0, self.alpha, 1.0 - self.alpha)
        return (alpha_t * focal).mean()


class DeepFM(nn.Module):
    def __init__(
        self,
        cat_cardinalities: Sequence[int],
        n_numeric: int,
        emb_dim: int = 8,
        hidden_dims: Sequence[int] = (256, 128, 64),
        dropout: float = 0.3,
        use_bn: bool = True,
    ):
        super().__init__()
        self.cat_cardinalities = [int(c) for c in cat_cardinalities]
        self.n_fields = len(self.cat_cardinalities)
        self.n_numeric = int(n_numeric)
        self.emb_dim = int(emb_dim)

        self.embeddings = nn.ModuleList(
            [nn.Embedding(card, self.emb_dim) for card in self.cat_cardinalities]
        )
        for emb in self.embeddings:
            nn.init.normal_(emb.weight, mean=0.0, std=0.01)

        self.linear_cats = nn.ModuleList(
            [nn.Embedding(card, 1) for card in self.cat_cardinalities]
        )
        for lin in self.linear_cats:
            nn.init.zeros_(lin.weight)

        self.linear_numeric = (
            nn.Linear(self.n_numeric, 1, bias=False) if self.n_numeric > 0 else None
        )
        self.bias = nn.Parameter(torch.zeros(1))

        in_dim = self.n_fields * self.emb_dim + self.n_numeric
        layers: List[nn.Module] = []
        cur = in_dim
        for h in hidden_dims:
            layers.append(nn.Linear(cur, int(h)))
            if use_bn:
                layers.append(nn.BatchNorm1d(int(h)))
            layers.append(nn.ReLU(inplace=True))
            layers.append(nn.Dropout(dropout))
            cur = int(h)
        self.deep = nn.Sequential(*layers)
        self.deep_out = nn.Linear(cur, 1)

    def forward(self, cat: torch.Tensor, numeric: Optional[torch.Tensor] = None):
        B = cat.size(0)
        linear = self.bias.expand(B)
        for i in range(self.n_fields):
            linear = linear + self.linear_cats[i](cat[:, i]).squeeze(-1)
        if self.n_numeric > 0 and numeric is not None:
            linear = linear + self.linear_numeric(numeric).squeeze(-1)

        embs = torch.stack(
            [self.embeddings[i](cat[:, i]) for i in range(self.n_fields)], dim=1
        )
        s = embs.sum(dim=1)
        sq = (embs**2).sum(dim=1)
        fm = 0.5 * (s**2 - sq).sum(dim=1)

        deep_in = embs.reshape(B, -1)
        if self.n_numeric > 0 and numeric is not None:
            deep_in = torch.cat([deep_in, numeric], dim=1)
        deep = self.deep_out(self.deep(deep_in)).squeeze(-1)
        return linear + fm + deep


def build_optimizer(model, lr=1e-3, weight_decay=1e-4):
    return torch.optim.AdamW(
        model.parameters(), lr=lr, weight_decay=weight_decay, betas=(0.9, 0.999)
    )


def build_scheduler(optimizer, epochs: int, mode="cosine", warmup_frac=0.1):
    epochs = max(int(epochs), 1)
    warm = max(int(round(epochs * warmup_frac)), 0)

    def lr_lambda(step: int) -> float:
        if warm > 0 and step < warm:
            return float(step + 1) / float(warm + 1)
        progress = (step - warm) / max(1, epochs - warm)
        progress = min(max(progress, 0.0), 1.0)
        if mode == "cosine":
            return 0.5 * (1.0 + math.cos(math.pi * progress))
        return max(0.0, 1.0 - progress)

    return torch.optim.lr_scheduler.LambdaLR(optimizer, lr_lambda)


def make_lightgbm(seed: int = 42, n_estimators: int = 900, n_jobs: int = 2):
    import lightgbm as lgb

    return lgb.LGBMClassifier(
        objective="binary",
        n_estimators=n_estimators,
        learning_rate=0.03,
        num_leaves=31,
        max_depth=-1,
        min_child_samples=25,
        subsample=0.8,
        subsample_freq=1,
        colsample_bytree=0.8,
        reg_alpha=0.05,
        reg_lambda=0.1,
        random_state=seed,
        n_jobs=n_jobs,
        verbose=-1,
    )


def make_meta_lgb(seed: int = 42):
    import lightgbm as lgb

    return lgb.LGBMClassifier(
        objective="binary",
        n_estimators=250,
        learning_rate=0.05,
        num_leaves=15,
        max_depth=4,
        min_child_samples=30,
        subsample=0.9,
        subsample_freq=1,
        colsample_bytree=0.9,
        random_state=seed,
        n_jobs=2,
        verbose=-1,
    )


try:
    from catboost import CatBoostClassifier  # noqa: F401

    _HAS_CB = True
except Exception:
    _HAS_CB = False


def _make_cb(seed: int = 42):
    if not _HAS_CB:
        return None
    return CatBoostClassifier(
        iterations=500,
        learning_rate=0.05,
        depth=6,
        l2_leaf_reg=3.0,
        random_seed=seed,
        verbose=False,
        thread_count=2,
        loss_function="Logloss",
    )


# ===========================================================================
# Step 3: Training / evaluation helpers
# ===========================================================================
def _to_str_list(series) -> List[str]:
    """Convert a Series to a pure list[str].

    Under pandas >= 2/4, `.astype(str).values.tolist()` on a string-extension
    dtype preserves NA markers (float('nan') / <NA>) instead of the literal
    'nan', which breaks `sorted()` and mixes types in `pd.Categorical`.
    This helper guarantees every element is a real Python str.
    """
    out = []
    for v in series.tolist():
        if v is None:
            out.append("nan")
        elif isinstance(v, str):
            out.append(v)
        else:
            try:
                if pd.isna(v):
                    out.append("nan")
                else:
                    out.append(str(v))
            except (TypeError, ValueError):
                out.append(str(v))
    return out


def _fit_cat_maps(fe_df, cat_cols):
    maps = {}
    for c in cat_cols:
        vals = sorted(set(_to_str_list(fe_df[c])))
        maps[c] = {v: (i + 1) for i, v in enumerate(vals)}
    return maps


def _transform_cat(fe_df, cat_cols, cat_maps):
    n = len(fe_df)
    arr = np.zeros((n, len(cat_cols)), dtype=np.int64)
    for i, c in enumerate(cat_cols):
        m = cat_maps[c]
        vals = _to_str_list(fe_df[c])
        arr[:, i] = np.array([m.get(v, 0) for v in vals], dtype=np.int64)
    return arr


def _numeric_block(fe_df, num_cols):
    if not num_cols:
        return np.zeros((len(fe_df), 0), dtype=np.float32)
    num_block = pd.DataFrame(
        {
            c: pd.to_numeric(fe_df[c], errors="coerce").astype(np.float64)
            for c in num_cols
        },
        index=fe_df.index,
    )
    return num_block.fillna(0.0).values.astype(np.float32)


def _prepare_features(fe_df, cat_cols, num_cols, cat_categories, fit):
    """Build a model frame: categoricals as pd.Categorical (native LGBM),
    numerics as float. Training categories are persisted for predict time."""
    data = {}
    for c in cat_cols:
        vals = _to_str_list(fe_df[c])
        if fit:
            cat_categories[c] = sorted(set(vals))
        cats = cat_categories.get(c, [])
        data[c] = pd.Categorical(vals, categories=cats)
    for c in num_cols:
        data[c] = (
            pd.to_numeric(fe_df[c], errors="coerce")
            .fillna(0.0)
            .values.astype(np.float64)
        )
    return pd.DataFrame(data, index=fe_df.index)


def _make_lgb_frame(df, cat_cols):
    """Accept a prepared DataFrame directly; ensure categorical dtype."""
    for c in cat_cols:
        if c in df.columns and not isinstance(df[c].dtype, pd.CategoricalDtype):
            df[c] = df[c].astype("category")
    return df


def _train_lgbm(df, y, cat_cols, seed=0, n_estimators=900):
    model = make_lightgbm(seed=seed, n_estimators=n_estimators, n_jobs=2)
    frame = _make_lgb_frame(df.copy(), cat_cols)
    model.fit(frame, y, categorical_feature=cat_cols)
    return model


def _predict_lgbm(model, df, cat_cols):
    frame = _make_lgb_frame(df.copy(), cat_cols)
    return model.predict_proba(frame)[:, 1]


def _cb_frame(fe_df, cb_cols):
    frame = fe_df[cb_cols].reset_index(drop=True).copy()
    for c in cb_cols:
        frame[c] = _to_str_list(fe_df[c])
    return frame


def _train_cb(fe_df, cb_cols, y, seed=0):
    m = _make_cb(seed=seed)
    if m is None:
        return None
    df = _cb_frame(fe_df, cb_cols)
    m.fit(df, y, cat_features=cb_cols)
    return m


def _predict_cb(model, fe_df, cb_cols):
    if model is None:
        return None
    df = _cb_frame(fe_df, cb_cols)
    return model.predict_proba(df)[:, 1]


def _train_deepfm(X_cat, X_num, y, card, epochs=18, batch_size=512, seed=0, lr=1e-3):
    torch.manual_seed(seed)
    np.random.seed(seed)
    device = "cpu"
    n = len(y)
    model = DeepFM(
        cat_cardinalities=card,
        n_numeric=X_num.shape[1],
        emb_dim=8,
        hidden_dims=(256, 128, 64),
        dropout=0.3,
        use_bn=True,
    ).to(device)
    criterion = FocalLoss(alpha=0.5, gamma=2.0)
    optimizer = build_optimizer(model, lr=lr, weight_decay=1e-4)
    sched = build_scheduler(optimizer, epochs=epochs, mode="cosine")

    Xc = torch.from_numpy(X_cat).long()
    Xn = torch.from_numpy(X_num).float()
    yt = torch.from_numpy(y.astype(np.float32))

    model.train()
    for _ in range(epochs):
        idx = torch.randperm(n)
        for i in range(0, n, batch_size):
            b = idx[i : i + batch_size]
            optimizer.zero_grad()
            logits = model(Xc[b], Xn[b])
            loss = criterion(logits, yt[b])
            loss.backward()
            optimizer.step()
        sched.step()
    return model


@torch.no_grad()
def _predict_deepfm(model, X_cat, X_num, batch_size=1024):
    model.eval()
    n = len(X_cat)
    out = np.zeros(n, dtype=np.float32)
    for i in range(0, n, batch_size):
        xc = torch.from_numpy(X_cat[i : i + batch_size]).long()
        xn = torch.from_numpy(X_num[i : i + batch_size]).float()
        out[i : i + batch_size] = torch.sigmoid(model(xc, xn)).cpu().numpy()
    return out


def _tune_threshold(probs, y):
    best_t, best_acc = 0.5, -1.0
    for t in np.linspace(0.2, 0.8, 61):
        acc = accuracy_score(y, (probs >= t).astype(int))
        if acc > best_acc:
            best_acc, best_t = float(acc), float(t)
    return best_t, best_acc


# ---------------------------------------------------------------------------
# TRAIN
# ---------------------------------------------------------------------------
def run_training(data_dir, model_dir):
    os.makedirs(model_dir, exist_ok=True)

    features, labels, schema = load_train_data(data_dir)
    y_raw = np.asarray(labels)
    uniq = sorted(set(y_raw.tolist()))
    label_map = {u: i for i, u in enumerate(uniq)}
    y = np.array([label_map[v] for v in y_raw], dtype=np.int64)

    # 5-fold OOF on TRAIN rows only, for threshold tuning.
    # Fit feature engineering separately inside each fold to avoid validation leakage.
    folds = make_stratified_folds(y, n_splits=5, seed=42)
    oof = np.zeros(len(y))
    for fi, (tr, va) in enumerate(folds):
        fe_fold = CouponFeatureEngineer()
        fe_fold.fit(features.iloc[tr])
        fe_tr = fe_fold.transform(features.iloc[tr])
        fe_va = fe_fold.transform(features.iloc[va])
        fold_cat_cols = list(fe_fold.categorical_columns)
        fold_num_cols = list(fe_fold.numeric_columns)
        fold_cat_categories = {}
        X_tr = _prepare_features(
            fe_tr, fold_cat_cols, fold_num_cols, fold_cat_categories, fit=True
        )
        X_va = _prepare_features(
            fe_va, fold_cat_cols, fold_num_cols, fold_cat_categories, fit=False
        )
        model = _train_lgbm(X_tr, y[tr], fold_cat_cols, seed=fi)
        oof[va] = _predict_lgbm(model, X_va, fold_cat_cols)
        print(
            f"[fold {fi}] acc="
            f"{accuracy_score(y[va], (oof[va] >= 0.5).astype(int)):.4f}"
        )

    thr, acc = _tune_threshold(oof, y)
    print(f"[OOF] LGB acc={acc:.6f} @ t={thr:.2f}")

    # Final models: fit preprocessing on all training rows after CV.
    fe = CouponFeatureEngineer()
    fe.fit(features)
    fe_train = fe.transform(features)
    cat_cols = list(fe.categorical_columns)
    num_cols = list(fe.numeric_columns)
    cat_categories = {}
    X_df = _prepare_features(fe_train, cat_cols, num_cols, cat_categories, fit=True)
    print(
        f"[train] rows={len(y)} cat={len(cat_cols)} num={len(num_cols)} "
        f"pos_rate={y.mean():.4f}"
    )

    # Single LGBM with 5-seed bagging on all training rows.
    final_models = [_train_lgbm(X_df, y, cat_cols, seed=s) for s in range(5)]

    bundle = {
        "fe": fe,
        "cat_cols": cat_cols,
        "num_cols": num_cols,
        "cat_categories": cat_categories,
        "lgb_models": final_models,
        "threshold": thr,
        "label_map": label_map,
    }
    joblib.dump(bundle, os.path.join(model_dir, "bundle.joblib"))
    print(f"[train] saved bundle to {model_dir}")
    print(f"Final Validation Score: {acc:.6f}")


# ---------------------------------------------------------------------------
# PREDICT (fresh process, read-only model)
# ---------------------------------------------------------------------------
def run_predict(data_dir, model_dir, output_path):
    features, schema = load_predict_data(data_dir)
    bundle = joblib.load(os.path.join(model_dir, "bundle.joblib"))

    fe = bundle["fe"]
    cat_cols = bundle["cat_cols"]
    num_cols = bundle["num_cols"]
    cat_categories = bundle["cat_categories"]
    label_map = bundle["label_map"]
    threshold = bundle["threshold"]

    fe_p = fe.transform(features)
    X_df = _prepare_features(fe_p, cat_cols, num_cols, cat_categories, fit=False)

    # Seed-bagged single LGBM: average probabilities across the 5 models.
    probs = np.mean(
        [_predict_lgbm(m, X_df, cat_cols) for m in bundle["lgb_models"]],
        axis=0,
    )

    preds_bin = (probs >= threshold).astype(int)
    inv_map = {int(v): k for k, v in label_map.items()}
    preds = np.array([inv_map[int(p)] for p in preds_bin])

    out_df = pd.DataFrame(
        {"row_id": np.arange(len(preds), dtype=np.int64), "prediction": preds}
    )
    out_dir = os.path.dirname(output_path)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    out_df.to_csv(output_path, index=False)
    print(f"[predict] wrote {len(out_df)} rows")


